    private static ClassNode node(byte[] bytes){ClassNode n=new ClassNode();new ClassReader(bytes).accept(n,ClassReader.EXPAND_FRAMES);return n;}
    private static byte[] write(ClassNode n){ClassWriter w=new ClassWriter(0);n.accept(w);return w.toByteArray();}
    private static byte[] bytes(ZipFile jar,String path){try{var e=jar.getEntry(path);return e==null?null:jar.getInputStream(e).readAllBytes();}catch(Exception e){throw new IllegalStateException(e);}}
